def solution(text):
    """Reverse only the alphabetic characters in the text, leaving all other characters in place."""
    letters = [ch for ch in text if ch.isalpha()]
    out = []
    for ch in text:
        if ch.isalpha():
            out.append(letters.pop())
        else:
            out.append(ch)
    return ''.join(out)
